/* 由 tools/extract-art.py 產生（請勿手改；重跑：python3 tools/extract-art.py）
 * Kai 的插圖（黑線＋白填色）去背素材，base64 內嵌，避免 file:// 下 canvas 被汙染。
 * KK.Art = { duo, wombat, stars:[3], meta, ready:Promise }
 *   duo    ：Kai＋小袋熊＋旗子（不含星星），寬 700
 *   duoSmall：同 duo 但去掉旗子與旗桿（各濾鏡小剪影用），寬 300
 *   wombat ：只有小袋熊（姊姊），高 256；含舉起的手與牽手的黑掌（不含 Kai 的手）
 *   stars  ：原圖的三顆星（由左至右），寬 96
 *   meta   ：錨點（duo 像素座標）：wombatInDuo{x,y,w,h}、stars[{cx,cy,w,h}]、footInDuo */
(function () {
  'use strict';
  var KK = (window.KK = window.KK || {});
  var D = {"palette": "warm", "duo": {"w": 700, "h": 620}, "wombat": {"w": 210, "h": 256}, "duoSmall": {"w": 300, "h": 230}, "wombatInDuo": {"x": 403.2, "y": 253.7, "w": 297.0, "h": 362.0}, "stars": [{"cx": 470.8, "cy": 171.0, "w": 96, "h": 97, "dw": 80.2, "dh": 81.2}, {"cx": 601.7, "cy": 193.6, "w": 96, "h": 96, "dw": 76.2, "dh": 76.2}, {"cx": 711.5, "cy": 277.3, "w": 96, "h": 101, "dw": 75.2, "dh": 79.2}], "footInDuo": {"kai": [109.3, 615.8], "wombat": [540.5, 610.7]}};
  var duo = new Image(), duoSmall = new Image(), wombat = new Image(), stars = [new Image(), new Image(), new Image()];
  function load(im, b64) {
    return new Promise(function (res) {
      im.onload = function () { res(); }; im.onerror = function () { res(); };
      im.src = 'data:image/png;base64,' + b64;
    }).then(function () { return im.decode ? im.decode().catch(function () {}) : 0; });
  }
  KK.Art = {
    duo: duo, duoSmall: duoSmall, wombat: wombat, stars: stars, meta: D, palette: 'warm',
    ready: Promise.all([
      load(duo, ''), load(duoSmall, ''), load(wombat, ''),
      load(stars[0], ''), load(stars[1], ''), load(stars[2], ''),
    ]).then(function () { return KK.Art; }),
  };
})();
